// The cast: 13 chibi characters cut from the sticker sheets (assets/stickers/<who>/<category>-<n>.webp, listed in
// stickerImages.ts, generated by tools/export_stickers.py). A scene such as 'lift' maps to the best-matching stickers.
import { STK as ALL_STK, type Who, type Sticker } from './stickerImages';
import { withoutBlocked } from './stickerBlock';
// every lookup below goes through this filtered copy, so a blocklisted sticker can never be shown
const STK = withoutBlocked(ALL_STK) as typeof ALL_STK;
export type { Who, Sticker };
export type Scene = string;
export const CHARS: Record<Who, string> = { asta: 'Asta', luffy: 'Luffy', naruto: 'Naruto', jinwoo: 'Jin-Woo', goku: 'Goku', kakashi: 'Kakashi', zoro: 'Zoro', gojo: 'Gojo', tanjiro: 'Tanjiro', killua: 'Killua', vegeta: 'Vegeta', zenitsu: 'Zenitsu', bakugo: 'Bakugo' };
export const WHO_LIST = (Object.keys(CHARS) as Who[]).filter((w) => Object.keys(STK[w] || {}).length);
const DAY_ORDER: Who[] = ['naruto', 'zoro', 'luffy', 'goku', 'tanjiro', 'gojo', 'asta']; // Sun..Sat
export const dayChar = (d = new Date()): Who => (STK[DAY_ORDER[d.getDay()]] && Object.keys(STK[DAY_ORDER[d.getDay()]]).length ? DAY_ORDER[d.getDay()] : WHO_LIST[d.getDay() % WHO_LIST.length]);
export const ACCENT: Record<Who, string> = { asta: '#e8b84a', luffy: '#e0443a', naruto: '#ff9a1f', jinwoo: '#7a5cff', goku: '#ff8a00', kakashi: '#8da2c0', zoro: '#3fae4a', gojo: '#7fc6ff', tanjiro: '#17a57a', killua: '#9fb7ff', vegeta: '#2f5fd0', zenitsu: '#ffc21a', bakugo: '#ff6a2a' };

export const SCENE_CATS: Record<string, string[]> = {
  lift: ['lift', 'sport'], sad: ['cry', 'confused', 'think', 'angry', 'smug'], drink: ['drink', 'boba'], eat: ['eat', 'noodles', 'burger', 'rice', 'pizza', 'boba'],
  scale: ['think', 'smug', 'confused'], walk: ['sport', 'hype'], run: ['sport', 'hype'], pushup: ['lift', 'sport'], task: ['laptop', 'study', 'read'], plan: ['study', 'read', 'laptop', 'think'],
  chart: ['thumbs', 'smug', 'laptop'], health: ['bath', 'chill', 'peace', 'sleep'], chef: ['noodles', 'eat', 'rice', 'burger'],
  habit: ['thumbs', 'lift', 'hype'], cheer: ['hype', 'laugh', 'party', 'thumbs'], wave: ['laugh', 'hype', 'peace', 'thumbs'],
  powerup: ['power', 'angry', 'lift', 'hype'], victory: ['party', 'hype', 'thumbs', 'laugh'], levelup: ['party', 'hype', 'laugh'], fight: ['power', 'angry', 'lift', 'sport'], dance: ['party', 'hype'],
  sleep: ['sleep', 'chill'], game: ['game', 'laptop'], love: ['love', 'laugh'], cool: ['cool', 'smug'], shock: ['shock', 'confused'], angry: ['angry'], think: ['think', 'confused', 'smug'],
};
const GENERIC = ['hype', 'laugh', 'thumbs', 'peace', 'smug', 'think'];

/** A sticker for these categories. `seed` keeps the pick stable; pass a changing seed to vary it. */
export function pickSticker(who: Who, cats: string[], seed = 0): Sticker {
  const w: Who = STK[who] ? who : WHO_LIST[0];
  const set = STK[w];
  for (const group of [cats, GENERIC]) {
    const pool = group.flatMap((c) => set[c] || []);
    if (pool.length) return pool[Math.abs(seed) % pool.length];
  }
  return Object.values(set).flat()[0];
}
export const stickerFor = (who: Who, scene: Scene, seed = 0): Sticker => pickSticker(who, SCENE_CATS[scene] || [scene], seed);
export const sprite = (who: Who, scene: Scene, seed = 0): number => stickerFor(who, scene, seed).src;

/** Look up one sticker by album id, e.g. 'zoro/hype-0'. */
export function stickerById(id: string): Sticker | undefined {
  const [who, name] = id.split('/');
  const set = STK[who as Who];
  if (!set) return undefined;
  for (const list of Object.values(set)) { const f = list.find((s) => s.name === name); if (f) return f; }
  return undefined;
}
export const stickersOf = (who: Who): Sticker[] => Object.values(STK[who] || {}).flat();
